SELECT N''P-Consumer-003'' AS CaptureLabel,@J AS CaptureJson,@Status AS OutputStatus,@Partial AS OutputPartial,@Error AS OutputError,@Message AS OutputMessage,DB_ID() AS FixtureDbId,@OwnedTableId AS FixtureTableId,@@OPTIONS AS CallerOptions,@@LOCK_TIMEOUT AS CallerLockTimeout,@@TRANCOUNT AS CallerTranCount,XACT_STATE() AS CallerXactState;
IF NOT EXISTS(SELECT 1 WHERE (SELECT COUNT(*) FROM OPENJSON(@J,''$.componentPhaseEvents''))=(SELECT COUNT(*) FROM @Cases)) THROW 56701,N''PHASE_GRAMMAR_COUNT'',1;
IF EXISTS(SELECT 1 FROM @Cases AS c FULL JOIN OPENJSON(@J,''$.componentPhaseEvents'') WITH(LogId int,ParseStatus varchar(40),ParserId varchar(32),ComponentId int,ComponentName nvarchar(4000),PhaseName varchar(32),ReportedDurationMs bigint,OutputId int,OutputName nvarchar(4000),ContextStatus varchar(40)) AS a ON a.LogId=c.LogId WHERE c.LogId IS NULL OR a.LogId IS NULL OR a.ParseStatus IS NULL OR a.ParseStatus<>c.ExpectedStatus OR (a.ParserId IS NULL AND c.ExpectedParser IS NOT NULL) OR (a.ParserId IS NOT NULL AND c.ExpectedParser IS NULL) OR a.ParserId<>c.ExpectedParser OR (c.ExpectedStatus<>''PARSED'' AND (a.ComponentId IS NOT NULL OR a.ComponentName IS NOT NULL OR a.PhaseName IS NOT NULL OR a.ReportedDurationMs IS NOT NULL OR a.OutputId IS NOT NULL OR a.OutputName IS NOT NULL OR a.ContextStatus<>''NOT_PARSED''))) THROW 56704,N''PHASE_GRAMMAR_MATRIX'',1;
