EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N''ExampleSsisPhaseLogSource'',@ExecutionId=@Id,@IncludeComponentPhaseAnalysis=1,@MaxZeilen=0,@HighImpactConfirmed=1,@ResultSetArt=''TABLE'',@JsonErzeugen=1,@Json=@J OUTPUT,@StatusCodeOut=@Status OUTPUT,@IsPartialOut=@Partial OUTPUT,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT,@ResultTablesJson=N''{"componentPhaseEvents":"#ExampleEn2Events","componentPhaseTimes":"#ExampleEn2Times"}''; SET @CiMarker=CONCAT(N''CI_AFTER|205|C038|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''-'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
SELECT N''P-EN2-Physical'' AS CaptureLabel,@J AS CaptureJson,@Status AS OutputStatus,@Partial AS OutputPartial,@Error AS OutputError,@Message AS OutputMessage;
IF @Error IS NOT NULL THROW 56736,N''PHASE_EN2_TABLE_ERROR'',1;
IF NOT EXISTS(SELECT 1 FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N''tempdb..#ExampleEn2Times'') AND name=N''ComponentId'' AND system_type_id=56 AND is_nullable=1) THROW 56737,N''PHASE_EN2_COMPONENT_NULL_FACET'',1;
DECLARE @En2Events nvarchar(max),@En2Times nvarchar(max);
EXEC sys.sp_executesql N''SELECT @E=(SELECT * FROM #ExampleEn2Events ORDER BY PhaseEventOrdinal FOR JSON PATH,INCLUDE_NULL_VALUES),@T=(SELECT * FROM #ExampleEn2Times ORDER BY PhaseTimeOrdinal FOR JSON PATH,INCLUDE_NULL_VALUES)'',N''@E nvarchar(max) OUTPUT,@T nvarchar(max) OUTPUT'',@E=@En2Events OUTPUT,@T=@En2Times OUTPUT;
IF @En2Events IS NULL OR @En2Times IS NULL OR JSON_QUERY(@J,''$.componentPhaseEvents'') IS NULL OR JSON_QUERY(@J,''$.componentPhaseTimes'') IS NULL OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key]=N''componentPhaseEvents'' AND type=4) OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key]=N''componentPhaseTimes'' AND type=4) OR CONVERT(varbinary(max),@En2Events)<>CONVERT(varbinary(max),JSON_QUERY(@J,''$.componentPhaseEvents'')) OR CONVERT(varbinary(max),@En2Times)<>CONVERT(varbinary(max),JSON_QUERY(@J,''$.componentPhaseTimes'')) THROW 56738,N''PHASE_EN2_TABLE_PARITY'',1;

IF NOT EXISTS(SELECT 1 WHERE @@OPTIONS=@Options AND @@LOCK_TIMEOUT=@Lock AND @@TRANCOUNT=@Tran AND XACT_STATE()=@Xact) THROW 56701,N''PHASE_CALLER'',1;
SELECT N''AVAILABLE'' AS StatusCode,N''SSIS reported component phase synthetic contract'' AS Detail;
END;');

 SELECT @ProcId=object_id FROM sys.procedures WITH (NOLOCK) WHERE schema_id=1 AND name COLLATE SQL_Latin1_General_CP1_CS_AS=N'ExampleSsisPhaseFixtureScope';
 IF @ProcId IS NULL THROW 56792,N'PHASE_OWN_PROC_NOT_CAPTURED',1;
 EXEC dbo.ExampleSsisPhaseFixtureScope @OwnedTableId=@TableId OUTPUT;
 IF DB_ID()<>@DbId OR OBJECT_ID(N'dbo.ExampleSsisPhaseLogSource')<>@TableId OR OBJECT_ID(N'dbo.ExampleSsisPhaseFixtureScope')<>@ProcId THROW 56793,N'PHASE_CLEANUP_BINDING',1;
 DROP TABLE dbo.ExampleSsisPhaseLogSource;
 DROP PROCEDURE dbo.ExampleSsisPhaseFixtureScope;
 IF @@OPTIONS<>@OuterOptions OR @@LOCK_TIMEOUT<>@OuterLock OR @@TRANCOUNT<>@OuterTran THROW 56794,N'PHASE_OUTER_CALLER',1;
END TRY
BEGIN CATCH
 DECLARE @OriginalError int=ERROR_NUMBER(),@OriginalMessage nvarchar(4000)=ERROR_MESSAGE();
 DECLARE @CleanupError nvarchar(4000)=N'',@ScopeValid bit=0;
 BEGIN TRY
  IF DB_ID()<>@DbId OR OBJECT_ID(N'tempdb..#ExampleSsisPhaseOwnership')<>@OwnershipId THROW 56795,N'PHASE_FAILURE_CLEANUP_SCOPE',1;
  SELECT @TableId=TableId,@UserId=UserId FROM #ExampleSsisPhaseOwnership;
  SET @ScopeValid=1;
 END TRY BEGIN CATCH SET @CleanupError=ERROR_MESSAGE(); END CATCH;
 IF @ScopeValid=1
 BEGIN
  BEGIN TRY
   IF @UserId IS NOT NULL AND EXISTS(SELECT 1 FROM sys.database_principals WITH (NOLOCK) WHERE principal_id=@UserId AND name COLLATE SQL_Latin1_General_CP1_CS_AS=N'ExamplePhaseLogReader') DROP USER ExamplePhaseLogReader;
  END TRY BEGIN CATCH SET @CleanupError+=N' User: '+ERROR_MESSAGE(); END CATCH;
  BEGIN TRY
   IF @TableId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleSsisPhaseLogSource')=@TableId DROP TABLE dbo.ExampleSsisPhaseLogSource;
  END TRY BEGIN CATCH SET @CleanupError+=N' Table: '+ERROR_MESSAGE(); END CATCH;
  BEGIN TRY
   IF @ProcId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleSsisPhaseFixtureScope')=@ProcId DROP PROCEDURE dbo.ExampleSsisPhaseFixtureScope;
  END TRY BEGIN CATCH SET @CleanupError+=N' Proc: '+ERROR_MESSAGE(); END CATCH;
 END;
 BEGIN TRY
  IF OBJECT_ID(N'tempdb..#ExampleSsisPhaseOwnership')=@OwnershipId DROP TABLE #ExampleSsisPhaseOwnership;
 END TRY BEGIN CATCH SET @CleanupError+=N' Temp: '+ERROR_MESSAGE(); END CATCH;
 SELECT @OriginalError AS OriginalError,@OriginalMessage AS OriginalMessage,@CleanupError AS CleanupError;
 THROW;
END CATCH;
DROP TABLE #ExampleSsisPhaseOwnership;
